INSERT INTO posts (id, author_id, post_type, category, title, excerpt, content, status, view_count, like_count, favorite_count, comment_count, published_at, created_at, updated_at)
VALUES
    ('10000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'GUIDE', '配队攻略', '长离焚火队：从零到毕业的配队思路', '围绕共鸣效率、轮切节奏与副 C 选择，整理一套能直接照着练的实战框架。', '## 先确定队伍节奏\n\n先用主输出完成关键技能循环，再让协同角色补充增益和伤害。不要为了追求面板而牺牲实际的轮切顺序。\n\n## 角色与声骸选择\n\n优先选择能覆盖队伍空窗期的协同角色。声骸方面，先满足套装效果，再根据主词条和副词条逐步替换。\n\n- 主输出优先保证共鸣技能循环\n- 协同位补充增益并缩短空窗期\n- 套装效果优先于单件面板', 'PUBLISHED', 18000, 3700, 1200, 46, '2026-09-14 10:24:00', '2026-09-14 10:24:00', '2026-09-14 10:24:00'),
    ('10000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000002', 'GUIDE', '深塔攻略', '2.4 深塔速通：低配阵容与手法拆解', '按房间记录怪物机制、起手顺序和容错点，附上可替换角色的思路。', '## 先看环境\n\n进入挑战前先确认本期环境和怪物机制，再安排队伍的轮切顺序。低配队伍更需要稳定的循环，而不是追求一次性的爆发数字。', 'PUBLISHED', 32000, 5100, 1800, 89, '2026-09-13 21:08:00', '2026-09-13 21:08:00', '2026-09-13 21:08:00'),
    ('10000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000003', 'GUIDE', '角色培养', '椿的声骸选择与词条优先级', '从套装、主词条到副词条阈值，说明不同武器与配队下的取舍。', '## 套装先于单件\n\n先满足套装效果，再根据队伍循环检查主词条和副词条。不要只看单件面板，实际轮切中的触发频率同样重要。', 'PUBLISHED', 25000, 3200, 900, 63, '2026-09-13 16:42:00', '2026-09-13 16:42:00', '2026-09-13 16:42:00'),
    ('10000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000004', 'GUIDE', '新手攻略', '新手开荒指南：从入坑到稳步成长', '主线推进、体力规划、角色资源和探索优先级，一次理清前两周要做什么。', '## 前两周的优先级\n\n先推进主线并解锁主要系统，再根据队伍需求安排角色资源。体力有限时，优先保证主力队伍的核心技能。', 'PUBLISHED', 51000, 8600, 3400, 112, '2026-09-12 19:30:00', '2026-09-12 19:30:00', '2026-09-12 19:30:00'),
    ('10000000-0000-0000-0000-000000000099', '10000000-0000-0000-0000-000000000001', 'GUIDE', '社区资讯', '已删除的测试帖子', '该帖子用于验证不可见内容不会泄露。', '已删除内容', 'DELETED', 0, 0, 0, 0, '2026-09-11 12:00:00', '2026-09-11 12:00:00', '2026-09-11 12:00:00');
